interface IWebhookHandler {
  handle(event: any): Promise<any>;
}

// Implement this interface in a service class
class WebhookService implements IWebhookHandler {
  constructor(private repository: IWebhookRepository) {}

  async handle(event: any): Promise<any> {
    const type = event.type;
    const data = event.data;

    // Validate the input data
    if (!this.isValidData(data)) {
      throw new Error('Invalid data');
    }

    // Process the data using the repository
    const processedData = await this.repository.process(data);

    return { processed: true, type, id: processedData.id };
  }

  private isValidData(data: any): boolean {
    // Add your validation logic here
    return data && typeof data === 'object' && 'id' in data;
  }
}

// Define an interface for the repository
