  process(data: any): Promise<any>;
}

// Implement the repository interface in a database adapter
class DatabaseAdapter implements IWebhookRepository {
  async process(data: any): Promise<any> {
    // Add your database processing logic here
    const processedData = { id: data.id, processed: true };
    return processedData;
  }
}

// Use dependency injection to inject the necessary components into the service
