  create(order: IOrder): Promise<void>;
}

class OrderRepository implements IOrderRepository {
  async create(order: IOrder): Promise<void> {
    const pgClient = new Client();
    await pgClient.connect();
    await pgClient.query('INSERT INTO orders (user_id, total) VALUES ($1, $2)', [order.userId, order.total]);
  }
}

// Controller Layer
